const $=id=>document.getElementById(id);
const map=L.map('map',{zoomControl:false}).setView([7.8,80.7],7);
L.control.zoom({position:'bottomright'}).addTo(map);
L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);
let data=[],filtered=[],layer,selected=null;
const cloud=f=>Number(f.properties['eo:cloud_cover']||0),date=f=>new Date(f.properties.datetime).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}),color=f=>cloud(f)<=20?'#35795d':cloud(f)<=60?'#c6a247':'#b76e55';
function select(f){selected=f.id;render();const box=L.geoJSON(f).getBounds();map.fitBounds(box,{padding:[60,60],maxZoom:10});const panel=$('detail');panel.replaceChildren();const img=document.createElement('img');img.src=f.assets.thumbnail.href;img.alt='Satellite preview of '+f.id;img.onerror=()=>img.remove();panel.append(img);const body=document.createElement('div');body.className='detail-body';body.innerHTML='<button class="close" aria-label="Close scene">×</button><h2>Scene details</h2><p></p><div class="detail-meta"><div><span>CLOUD COVER</span><b></b></div><div><span>PLATFORM</span><b></b></div></div>';body.querySelector('p').textContent=date(f)+' · '+f.id;body.querySelectorAll('b')[0].textContent=cloud(f).toFixed(1)+'%';body.querySelectorAll('b')[1].textContent=f.properties.platform;body.querySelector('button').onclick=()=>{selected=null;panel.replaceChildren();render()};const a=document.createElement('a');a.className='action';a.textContent='Open original RGB on Amazon S3 ↗';a.href=f.assets.visual.href;a.target='_blank';a.rel='noopener';body.append(a);const note=document.createElement('p');note.className='small';note.style.marginTop='10px';note.textContent='Full-resolution GeoTIFF · large file; opens or downloads in a new tab.';body.append(note);panel.append(body)}
function render(){filtered=data.filter(f=>cloud(f)<=Number($('cloud').value)).sort((a,b)=>$('sort').value==='cloud'?cloud(a)-cloud(b):new Date(b.properties.datetime)-new Date(a.properties.datetime));$('cloudValue').textContent=$('cloud').value+'%';$('count').textContent=filtered.length+' scenes';$('total').textContent=filtered.length;$('clear').textContent=filtered.filter(f=>cloud(f)<20).length;if(layer)map.removeLayer(layer);layer=L.geoJSON(filtered,{style:f=>({color:color(f),weight:f.id===selected?3:1,fillOpacity:f.id===selected?.35:.08}),onEachFeature:(f,l)=>{l.bindTooltip(date(f)+' · '+cloud(f).toFixed(1)+'% cloud');l.on('click',()=>select(f))}}).addTo(map);$('list').replaceChildren();if(!filtered.length){$('list').innerHTML='<p class="empty">No scenes match this cloud limit. Increase the slider to explore more.</p>';return}filtered.forEach(f=>{const b=document.createElement('button');b.className='scene'+(selected===f.id?' active':'');const img=document.createElement('img');img.src=f.assets.thumbnail.href;img.alt='';img.loading='lazy';img.onerror=()=>img.style.visibility='hidden';const text=document.createElement('div');const title=document.createElement('strong');title.textContent=date(f);const sub=document.createElement('small');sub.textContent=f.id;const chip=document.createElement('span');chip.className='chip';chip.textContent=cloud(f).toFixed(1)+'% cloud';text.append(title,sub,chip);b.append(img,text);b.onclick=()=>select(f);$('list').append(b)})}
$('cloud').oninput=()=>{selected=null;$('detail').replaceChildren();render()};$('sort').onchange=render;$('reset').onclick=()=>{if(filtered.length)map.fitBounds(layer.getBounds(),{padding:[35,35]})};$('aboutLink').onclick=e=>{e.preventDefault();$('about').showModal()};$('closeAbout').onclick=()=>$('about').close();$('export').onclick=()=>{const features=filtered.map(f=>({type:'Feature',id:f.id,geometry:f.geometry,properties:{datetime:f.properties.datetime,cloud_cover:cloud(f),platform:f.properties.platform,thumbnail:f.assets.thumbnail.href,rgb:f.assets.visual.href}}));const url=URL.createObjectURL(new Blob([JSON.stringify({type:'FeatureCollection',features},null,2)],{type:'application/geo+json'}));const a=document.createElement('a');a.href=url;a.download='clear-skies-scenes.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
fetch('scenes.json').then(r=>{if(!r.ok)throw Error('dataset unavailable');return r.json()}).then(d=>{data=d.features;if(!data.length)throw Error('empty dataset');render();$('reset').click()}).catch(()=>{$('list').innerHTML='<p class="empty">The scene catalog could not load. Please reload the page to try again.</p>'});
